<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, watch } from 'vue';
import cytoscape from 'cytoscape';
import type { Core } from 'cytoscape';
import type { Analysis } from '../model';
import { cycleIds } from '../model';
import { Plus, Minus, Maximize, RefreshCw } from 'lucide-vue-next';
const props = defineProps<{data:Analysis; selected:string|null; cyclesOnly:boolean}>();
const emit = defineEmits<{select:[id:string]}>();
const container = ref<HTMLDivElement>(); let cy:Core|undefined; let observer:ResizeObserver|undefined;
function render(){if(!container.value)return;cy?.destroy();const circular=cycleIds(props.data);cy=cytoscape({container:container.value,elements:[...props.data.nodes.map(n=>({data:{id:n.id,label:n.label},classes:circular.has(n.id)?'circular':''})),...props.data.edges.filter(e=>props.data.nodes.some(n=>n.id===e.source)&&props.data.nodes.some(n=>n.id===e.target)).map((e,i)=>({data:{id:`edge-${i}`,source:e.source,target:e.target},classes:props.data.cycles.some(group=>group.includes(e.source)&&group.includes(e.target))?'circular':''}))],style:[{selector:'node',style:{'shape':'round-rectangle','background-color':'#242537','border-width':1.5,'border-color':'#77728d','label':'data(label)','color':'#e4e2ed','font-family':'Inter, ui-sans-serif, system-ui','font-size':11,'text-valign':'center','text-halign':'center','width':130,'height':43,'text-wrap':'ellipsis','text-max-width':'118px'}},{selector:'edge',style:{'width':1.2,'line-color':'#494759','target-arrow-color':'#747085','target-arrow-shape':'triangle','curve-style':'bezier','arrow-scale':0.75}},{selector:'node.circular',style:{'background-color':'#392b30','border-color':'#d58c6b'}},{selector:'edge.circular',style:{'line-color':'#bd8065','target-arrow-color':'#bd8065','line-style':'dashed'}},{selector:'node:selected',style:{'border-color':'#c5b4ff','border-width':2.5,'background-color':'#3c315a','color':'#ffffff'}},{selector:'.dim',style:{'opacity':0.12}}],layout:{name:'cose',animate:false,padding:55,nodeRepulsion:()=>16000,idealEdgeLength:()=>135,componentSpacing:100},wheelSensitivity:0.22,minZoom:0.15,maxZoom:3});cy.on('tap','node',e=>emit('select',e.target.id()));applySelection();applyFilter();}
function applySelection(){cy?.nodes().unselect();if(props.selected)cy?.getElementById(props.selected).select();}
function applyFilter(){cy?.elements().removeClass('dim');if(props.cyclesOnly)cy?.elements().not('.circular').addClass('dim');}
function zoom(delta:number){if(cy)cy.zoom({level:cy.zoom()*delta,renderedPosition:{x:cy.width()/2,y:cy.height()/2}})}
onMounted(()=>{render();observer=new ResizeObserver(()=>{cy?.resize()});if(container.value)observer.observe(container.value)});onBeforeUnmount(()=>{observer?.disconnect();cy?.destroy()});watch(()=>props.data,render);watch(()=>props.selected,applySelection);watch(()=>props.cyclesOnly,applyFilter);
</script>
<template><div class="graph-wrap"><div ref="container" class="graph-canvas" role="img" aria-label="Interactive module dependency graph. Select a module in the modules list for keyboard-accessible details."></div><div class="graph-controls"><button title="Zoom in" aria-label="Zoom in" @click="zoom(1.25)"><Plus :size="17"/></button><button title="Zoom out" aria-label="Zoom out" @click="zoom(0.8)"><Minus :size="17"/></button><span></span><button title="Fit graph" aria-label="Fit graph" @click="cy?.fit(undefined,50)"><Maximize :size="16"/></button><button title="Rearrange graph" aria-label="Rearrange graph" @click="render"><RefreshCw :size="16"/></button></div><div class="graph-hint">Scroll to zoom <span>·</span> Drag to explore</div></div></template>
